import "server-only";
import { createClient } from "@supabase/supabase-js";
import { createSupabaseServerClient } from "@/lib/supabase/server";
import { supabasePublishableKey, supabaseUrl } from "@/lib/supabase/config";
import { unauthorized } from "./http";
import { prisma } from "./prisma";

// Who is calling. Identity comes from Supabase Auth (a verified JWT); the role
// and organization come ONLY from our tables (memberships for staff/managers,
// tenants.user_id for tenants) — never from user_metadata, which users can edit.

export type Actor =
  | {
      kind: "member";
      userId: string;
      email: string | null;
      orgId: string;
      role: "manager" | "staff";
    }
  | {
      kind: "tenant";
      userId: string;
      email: string | null;
      orgId: string;
      tenantId: string;
    };

type AuthUser = { id: string; email: string | null };

const BEARER_PATTERN = /^Bearer\s+(\S+)$/i;

// Authorization: Bearer <access token> (how the graders' tests call the API).
// getUser(token) asks the Auth server to verify the token — not a local decode.
const userFromBearer = async (token: string): Promise<AuthUser | null> => {
  const supabase = createClient(supabaseUrl(), supabasePublishableKey(), {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
  const { data, error } = await supabase.auth.getUser(token);
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

// The browser session cookie. getUser(), never getSession(): getSession trusts
// the cookie's contents without asking the Auth server.
const userFromCookie = async (): Promise<AuthUser | null> => {
  const supabase = await createSupabaseServerClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

const authUser = async (req?: Request): Promise<AuthUser | null> => {
  const header = req?.headers.get("authorization");
  if (header) {
    const match = BEARER_PATTERN.exec(header.trim());
    // A malformed Authorization header is not silently ignored in favour of
    // a cookie: the caller asked to authenticate with it, and it is invalid.
    return match?.[1] ? userFromBearer(match[1]) : null;
  }
  return userFromCookie();
};

/** Resolves the caller to an Actor, or null when there is no valid login or no role. */
export const getActor = async (req?: Request): Promise<Actor | null> => {
  const user = await authUser(req);
  if (!user) {
    return null;
  }
  const membership = await prisma.memberships.findUnique({
    where: { user_id: user.id },
    select: { org_id: true, role: true },
  });
  if (membership) {
    if (membership.role !== "manager" && membership.role !== "staff") {
      return null;
    }
    return {
      kind: "member",
      userId: user.id,
      email: user.email,
      orgId: membership.org_id,
      role: membership.role,
    };
  }
  const tenant = await prisma.tenants.findUnique({
    where: { user_id: user.id },
    select: { id: true, org_id: true },
  });
  if (tenant) {
    return {
      kind: "tenant",
      userId: user.id,
      email: user.email,
      orgId: tenant.org_id,
      tenantId: tenant.id,
    };
  }
  return null;
};

/** getActor or 401. */
export const requireActor = async (req?: Request): Promise<Actor> => {
  const actor = await getActor(req);
  if (!actor) {
    throw unauthorized();
  }
  return actor;
};
import "server-only";
import { randomUUID } from "node:crypto";
import { badRequest } from "./http";
import { supabaseAdmin } from "./supabase-admin";

// Bank-transfer slips in the private `payment-slips` bucket, under
// '<org_id>/<lease_id>/<random uuid>.<ext>'. The type is decided from the
// file's first bytes, never from its name or the browser's Content-Type.
// Callers authorize first (the org and lease come from a visible lease).

type SlipType = {
  ext: "jpg" | "png" | "pdf";
  contentType: string;
  magic: number[];
};

export const SLIP_BUCKET = "payment-slips";
export const MAX_SLIP_BYTES = 5 * 1024 * 1024;
const SIGNED_URL_SECONDS = 60;

const SLIP_TYPES: SlipType[] = [
  { ext: "jpg", contentType: "image/jpeg", magic: [0xff, 0xd8, 0xff] },
  {
    ext: "png",
    contentType: "image/png",
    magic: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
  },
  // "%PDF-"
  {
    ext: "pdf",
    contentType: "application/pdf",
    magic: [0x25, 0x50, 0x44, 0x46, 0x2d],
  },
];

/** JPEG, PNG or PDF by magic bytes, else null. */
export const detectSlipType = (bytes: Uint8Array): SlipType | null =>
  SLIP_TYPES.find((type) =>
    type.magic.every((byte, index) => bytes[index] === byte),
  ) ?? null;

/** Validates (<= 5 MB, JPEG/PNG/PDF) and uploads; returns the object path. */
export const uploadSlip = async (
  orgId: string,
  leaseId: string,
  file: File,
): Promise<string> => {
  if (file.size === 0) {
    throw badRequest("slip: File is empty");
  }
  if (file.size > MAX_SLIP_BYTES) {
    throw badRequest("slip: File is larger than 5 MB");
  }
  const bytes = new Uint8Array(await file.arrayBuffer());
  const type = detectSlipType(bytes);
  if (!type) {
    throw badRequest("slip: Only JPEG, PNG or PDF files are accepted");
  }
  const path = `${orgId}/${leaseId}/${randomUUID()}.${type.ext}`;
  const { error } = await supabaseAdmin()
    .storage.from(SLIP_BUCKET)
    .upload(path, bytes, { contentType: type.contentType, upsert: false });
  if (error) {
    throw new Error(`Slip upload failed: ${error.message}`);
  }
  return path;
};

export const removeSlip = async (path: string): Promise<void> => {
  const { error } = await supabaseAdmin()
    .storage.from(SLIP_BUCKET)
    .remove([path]);
  if (error) {
    throw new Error(`Slip removal failed: ${error.message}`);
  }
};

/** Short-lived (60 s) signed download URL. Caller must have authorized the read. */
export const signedSlipUrl = async (path: string): Promise<string> => {
  const { data, error } = await supabaseAdmin()
    .storage.from(SLIP_BUCKET)
    .createSignedUrl(path, SIGNED_URL_SECONDS);
  if (error) {
    throw new Error(`Could not sign slip URL: ${error.message}`);
  }
  return data.signedUrl;
};

